{
  "avaliacoes": [
    {
      "id": "E0071aa23e0604bb0",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "No alerta, lacunas em JSAs para içamentos e trabalhos com potencial de queda de objetos incluem ausência de verificação visual no local, uso de texto pré-impresso sem análise adicional e negação do perigo de queda de objetos em certas atividades de levantamento.",
          "trechos": [
            "E0071aa23e0604bb0:0:696"
          ],
          "condicoes": [
            "Achado observado nas inspeções baseadas em risco referidas pelo BSEE",
            "Aplica-se às atividades e instalações efetivamente inspecionadas"
          ],
          "limites": [
            "Alerta regulatório dos EUA, sem conversão automática em requisito brasileiro",
            "O trecho não define formato obrigatório de JSA nem integração com PT ou APR"
          ]
        },
        {
          "proposicao": "O alerta descreve como práticas presentes a comunicação com bases e plataformas, marcações por cor e forma, inspeção pré-uso de lingas e rigging e inspeções pré-levantamento de cargas, apresentando-as como medidas associadas ao controle de perigos em movimentação de cargas.",
          "trechos": [
            "E0071aa23e0604bb0:696:1392"
          ],
          "condicoes": [
            "Relato das instalações inspecionadas nas quais tais práticas estavam implantadas",
            "Relaciona-se a cargas como contêineres, tubulares e outras cargas mencionadas"
          ],
          "limites": [
            "O trecho não demonstra eficácia quantitativa nem estabelece hierarquia formal de controles",
            "Não especifica critérios operacionais de segregação física ou dimensões de zonas de exclusão"
          ]
        },
        {
          "proposicao": "O BSEE recomenda desenvolver estratégia e plano de prevenção de queda de objetos, estabelecer frequências regulares de inspeção com registro, criar treinamento específico para pessoas expostas ou inspetoras e assegurar que novos equipamentos ou estruturas acionem o processo de gestão de mudanças para tratar perigos introduzidos.",
          "trechos": [
            "E0071aa23e0604bb0:1392:2088",
            "E0071aa23e0604bb0:2088:2340"
          ],
          "condicoes": [
            "Apresentado como recomendação do alerta após resultados de inspeção",
            "Inclui mudanças como montagem de novos acessórios, estruturas ou equipamentos em altura"
          ],
          "limites": [
            "Não define periodicidades numéricas, conteúdo mínimo de treinamento ou método único de inspeção",
            "Recomendação setorial do contexto do alerta, não prova experimental controlada"
          ]
        }
      ]
    },
    {
      "id": "E892b30407726ed49",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A fonte descreve, como prática offshore normal para cargas longas, equipe de operação de guindaste composta por operador, banksman e dois slingers, pois a conexão e desconexão em cargas compridas pode exigir atuação em ambas as extremidades.",
          "trechos": [
            "E892b30407726ed49:0:690"
          ],
          "condicoes": [
            "Referido a cargas classificáveis como longas, como tubulares de perfuração",
            "Inserido em descrição operacional de movimentação mecânica offshore"
          ],
          "limites": [
            "Não deve ser convertido em composição obrigatória universal para todo FPSO ou toda carga",
            "O trecho não trata de qualificação mínima, capacidade do equipamento ou critérios de escolha da equipe"
          ]
        },
        {
          "proposicao": "Para operações com guindaste, a fonte identifica dois perigos principais para pessoas: ser atingido por carga que cai e ser atingido por carga oscilante; associa queda de carga à falha do equipamento de içamento ou ao colapso da carga, e a oscilação a parada ou movimento súbito, estado do mar, vento, erro do operador ou liberação repentina de carga presa.",
          "trechos": [
            "E892b30407726ed49:690:1387"
          ],
          "condicoes": [
            "Aplica-se ao contexto de operações de guindaste descritas na fonte"
          ],
          "limites": [
            "Explicação técnica geral, sem matriz de risco, probabilidade ou severidade quantificada",
            "Exemplos citados decorrem do contexto offshore do documento"
          ]
        },
        {
          "proposicao": "A fonte define 'danger zone' como a área abaixo de uma carga onde uma carga em queda pode atingir ou a área ao redor de uma carga para onde ela pode oscilar; como política técnica, afirma que, quando praticável, não se deve içar sobre pessoas ou áreas ocupadas e, quando isso não for razoavelmente praticável, devem existir medidas de proteção ou sistema seguro de trabalho para excluir pessoas da zona de perigo.",
          "trechos": [
            "E892b30407726ed49:1387:1998"
          ],
          "condicoes": [
            "Aplicado ao perigo de queda e de oscilação de carga em operações de içamento",
            "Admite situação em que evitar sobrevoo de pessoas não seja razoavelmente praticável"
          ],
          "limites": [
            "Documento de orientação do Reino Unido, não requisito brasileiro automático",
            "O trecho não informa como dimensionar a zona de perigo nem quais barreiras específicas adotar"
          ]
        }
      ]
    },
    {
      "id": "E32bac87b4e79d35b",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "A fonte relata situação em que o método expunha a tripulação a permanência sob carga suspensa, e a mudança posterior do método pelo responsável é apresentada como evidência de falha tanto na avaliação de riscos quanto no monitoramento de conformidade do próprio detentor do dever.",
          "trechos": [
            "E32bac87b4e79d35b:0:697"
          ],
          "condicoes": [
            "Referido ao exemplo inspecionado no documento de controle de trabalho"
          ],
          "limites": [
            "Exemplo de fiscalização, não estudo experimental controlado",
            "Não fornece procedimento substituto detalhado para a operação"
          ]
        },
        {
          "proposicao": "Segundo a fonte, a permissão de trabalho deve enfatizar os perigos-chave e os controles de risco técnicos ou procedimentais necessários para evitar dano, destacando que atividades offshore como trabalho em altura, eletricidade, sistemas pressurizados não hidrocarbonetos, entrada em espaço confinado e içamento podem resultar previsivelmente em morte ou lesão de uma ou mais pessoas.",
          "trechos": [
            "E32bac87b4e79d35b:0:697",
            "E32bac87b4e79d35b:697:1395"
          ],
          "condicoes": [
            "Referido ao uso de sistemas formais de controle de trabalho e PTW ou WCC"
          ],
          "limites": [
            "Documento orientativo do Reino Unido, sem equivalência automática a formulário brasileiro específico",
            "Não define lista fechada de controles para cada tarefa crítica"
          ]
        },
        {
          "proposicao": "A fonte adverte que permissões infladas por muitos perigos triviais e controles irrelevantes podem encobrir os perigos-chave e favorecer cópia de documentos entre trabalhos, normalizando avaliações pouco críticas; também relata que alguns operadores retiraram atividades rotineiras e de baixo perigo do sistema formal para concentrar a avaliação e o monitoramento.",
          "trechos": [
            "E32bac87b4e79d35b:1395:2071"
          ],
          "condicoes": [
            "Discussão feita no contexto de sistemas formais de controle de trabalho como ISSOW"
          ],
          "limites": [
            "O trecho não oferece critério objetivo para separar atividade rotineira de atividade que deve permanecer no sistema formal",
            "Não trata especificamente de linha de fogo ou de zonas de exclusão além do contexto geral de perigos-chave"
          ]
        }
      ]
    },
    {
      "id": "E5a5d520b6bc42829",
      "pertinente": true,
      "tipo": "indeterminado",
      "achados": [
        {
          "proposicao": "O trecho afirma que desvio temporário de camadas de proteção de sistemas de segurança e contingenciamento deve ser precedido por análise de riscos que explicite medidas provisórias para prevenir danos às instalações, às pessoas ou ao processo produtivo e manter o risco em níveis aceitáveis.",
          "trechos": [
            "E5a5d520b6bc42829:0:699"
          ],
          "condicoes": [
            "Referido a desvio temporário de camadas de proteção",
            "As medidas provisórias devem estar claras na análise de riscos"
          ],
          "limites": [
            "Fonte com fronteiras documentais não identificadas no pacote",
            "Não detalha método de análise, critérios de aceitabilidade nem controles específicos para içamento ou queda de objetos"
          ]
        },
        {
          "proposicao": "Na elaboração de projeto para escavação e intervenções no solo, o trecho lista como fatores a considerar o método executivo, área de influência, exequibilidade, riscos às instalações existentes, verificações in loco e pesquisa de documentação técnica, ilustrando seleção de controles a partir das características da intervenção e do entorno.",
          "trechos": [
            "E5a5d520b6bc42829:699:1397"
          ],
          "condicoes": [
            "Aplicável ao contexto de escavação e intervenção no solo citado"
          ],
          "limites": [
            "Baixa aderência direta ao recorte de FPSO, por tratar de solo ou empreendimento terrestre",
            "Não informa como esses fatores se traduzem em barreiras operacionais concretas"
          ]
        },
        {
          "proposicao": "O trecho menciona padrão interno para trabalhos em espaços confinados com finalidade de orientar, treinar, planejar, controlar e proteger trabalhadores, inclusive com medidas para resgate em emergência, e outro para trabalhos em altura voltado a identificar riscos e executar atividades com métodos e equipamentos necessários para preservar a saúde e a segurança.",
          "trechos": [
            "E5a5d520b6bc42829:699:1397",
            "E5a5d520b6bc42829:1397:2089"
          ],
          "condicoes": [
            "Apresentado no contexto de padrões internos referidos pela fonte"
          ],
          "limites": [
            "Não há detalhamento dos critérios operacionais desses padrões no trecho",
            "Não trata explicitamente de zonas de exclusão, linha de fogo ou prevenção de queda de objetos"
          ]
        }
      ]
    },
    {
      "id": "E7a8997f2485d4d54",
      "pertinente": true,
      "tipo": "indeterminado",
      "achados": [
        {
          "proposicao": "Para trabalhos sobre o mar, o trecho condiciona a execução a elementos como iluminação adequada no local, medição da velocidade do vento no próprio local de execução e consideração, na APN-2, das condições de vento e mar para descida do bote de resgate, realização do resgate e retorno à instalação.",
          "trechos": [
            "E7a8997f2485d4d54:0:699"
          ],
          "condicoes": [
            "Aplica-se a trabalhos sobre o mar no documento de origem não identificado",
            "As condições de vento e mar devem ser consideradas especificamente para o cenário de resgate mencionado"
          ],
          "limites": [
            "Fonte documental não identificada de forma independente no pacote",
            "Não informa limites numéricos de vento, mar ou critérios de aceitação"
          ]
        },
        {
          "proposicao": "O trecho estabelece que, durante trabalhos sobre o mar, o bote de resgate deve estar operacional, com tripulação treinada e de sobreaviso; se isso não ocorrer, deve ser prevista embarcação de apoio próxima à instalação com recursos de resgate, e é indicada a presença de observador com rádio para comunicação com os envolvidos e a sala de rádio.",
          "trechos": [
            "E7a8997f2485d4d54:699:1396"
          ],
          "condicoes": [
            "Referido à execução de trabalhos sobre o mar",
            "A alternativa de embarcação de apoio aparece para a condição de indisponibilidade do bote de resgate"
          ],
          "limites": [
            "Sem confirmação de status legal do documento no trecho fornecido",
            "Não especifica distância da embarcação de apoio nem requisitos detalhados de comunicação"
          ]
        },
        {
          "proposicao": "O texto afirma que trabalhos em moonpool de sondas e em turret de FPSO e FSO podem não ser classificados como trabalho sobre o mar desde que exista procedimento específico; também indica que trabalhos em plataformas de andaimes montados sobre o mar podem deixar de ser classificados dessa forma se forem atendidas condições cumulativas ligadas à conformidade do andaime, acesso interno sem risco de queda ao mar, inspeção e liberação conjunta e constatação de controle do risco de queda.",
          "trechos": [
            "E7a8997f2485d4d54:1396:2073",
            "E7a8997f2485d4d54:0:699"
          ],
          "condicoes": [
            "Dependente de procedimento específico para moonpool e turret",
            "Dependente do atendimento das condições listadas para andaimes sobre o mar"
          ],
          "limites": [
            "O trecho não apresenta o conteúdo do procedimento específico nem critérios de validação",
            "A menção a sondas e FSO exige cuidado para não generalizar diretamente para todas as áreas de FPSO"
          ]
        }
      ]
    }
  ],
